Voici une fonction héritée qui calcule le total d'une commande. Elle est en production et des clients dépendent de son comportement exact.

```js
var TVA = 0.2;
var log = [];
function calc(o) {
  var t = 0;
  for (var i = 0; i < o.items.length; i++) {
    var it = o.items[i];
    if (it.q > 0) {
      if (it.cat == 'livre') {
        t = t + it.p * it.q * 0.95;
      } else {
        if (it.q >= 10) {
          t = t + it.p * it.q * 0.9;
        } else {
          t = t + it.p * it.q;
        }
      }
    }
  }
  if (o.code == 'BIENVENUE' && t > 50) {
    t = t - 10;
  }
  if (o.client == 'pro') {
    var ht = t;
  } else {
    var ht = t / (1 + TVA);
  }
  var port = 0;
  if (o.pays == 'FR') {
    if (t < 60) port = 4.9;
  } else if (o.pays == 'BE' || o.pays == 'LU') {
    port = t < 100 ? 9.9 : 0;
  } else {
    port = 19.9;
  }
  var total = Math.round((t + port) * 100) / 100;
  log.push(o.id + ':' + total);
  return { total: total, ht: Math.round(ht * 100) / 100, port: port };
}
```

