```ts
import express from 'express';
import { db } from './db';

const app = express();
app.use(express.json());

const sessions = new Map<string, { userId: string }>();

app.get('/api/users/:id/invoices', async (req, res) => {
  const userId = req.params.id;
  const status = req.query.status ?? 'paid';
  const rows = await db.query(`SELECT * FROM invoices WHERE user_id = ${userId} AND status = '${status}'`);
  res.json(rows);
});

app.post('/api/transfer', async (req, res) => {
  const { from, to, amount } = req.body;
  const [account] = await db.query('SELECT balance FROM accounts WHERE id = ?', [from]);
  if (account.balance >= amount) {
    await db.query('UPDATE accounts SET balance = balance - ? WHERE id = ?', [amount, from]);
    await db.query('UPDATE accounts SET balance = balance + ? WHERE id = ?', [amount, to]);
  }
  res.json({ ok: true });
});

app.get('/api/profile', async (req, res) => {
  const token = req.headers.authorization ?? '';
  const session = sessions.get(token);
  const [user] = await db.query('SELECT * FROM users WHERE id = ?', [session?.userId]);
  res.json(user);
});

app.use((err: Error, _req: express.Request, res: express.Response, _next: express.NextFunction) => {
  res.status(500).json({ error: err.message, stack: err.stack });
});

app.listen(3000);
```

